// Pull the identifiers out of whatever shape arrived.
// Meta sends a thin webhook: leadgen_id + ad/form ids, no PII.
// The manual test path sends a flat lead object instead.
const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const change = b?.entry?.[0]?.changes?.[0]?.value;

  if (change?.leadgen_id) {
    out.push({
      json: {
        source: 'meta_webhook',
        event_id: `${change.leadgen_id}`,
        lead_id: `${change.leadgen_id}`,
        form_id: change.form_id ?? '',
        ad_id: change.ad_id ?? '',
        adgroup_id: change.adgroup_id ?? '',
        page_id: change.page_id ?? '',
        created_time: change.created_time ?? null,
        needs_graph_fetch: true,
      },
    });
    continue;
  }

  // Test / manual payload — already has the lead fields.
  if (b?.lead_id) {
    out.push({
      json: {
        source: b.source ?? 'manual_test',
        event_id: `${b.event_id ?? b.lead_id}`,
        lead_id: `${b.lead_id}`,
        full_name: b.name ?? b.full_name ?? '',
        first_name: b.first_name ?? '',
        last_name: b.last_name ?? '',
        phone_raw: b.phone ?? '',
        email: b.email ?? '',
        campaign_id: b.campaign_id ?? '',
        campaign_name: b.campaign_name ?? '',
        ad_id: b.ad_id ?? '',
        ad_name: b.ad_name ?? '',
        form_id: b.form_id ?? '',
        form_name: b.form_name ?? '',
        inbound_message: b.message ?? '',
        needs_graph_fetch: false,
      },
    });
  }
}

if (out.length === 0) {
  throw new Error('No usable lead identifier in payload');
}

return out;

// Flatten Meta's field_data array into named fields, and keep every
// custom question the form asked. Fails loudly if Graph rejected us —
// a silent empty lead is worse than a stopped run.
const src = $('Extract Lead Event').first().json;
const res = $input.first().json;
const status = res.statusCode ?? 200;
const body = res.body ?? res;

if (status >= 400 || body?.error) {
  throw new Error(`Meta Graph API failed (${status}): ${body?.error?.message ?? 'unknown'}`);
}

const fields = {};
for (const f of body.field_data ?? []) {
  fields[f.name] = Array.isArray(f.values) ? f.values[0] : f.values;
}

const pick = (...keys) => {
  for (const k of keys) if (fields[k]) return fields[k];
  return '';
};

const full = pick('full_name', 'name');
const first = pick('first_name') || full.split(' ')[0] || '';
const last = pick('last_name') || full.split(' ').slice(1).join(' ');

return [{
  json: {
    ...src,
    full_name: full || `${first} ${last}`.trim(),
    first_name: first,
    last_name: last,
    phone_raw: pick('phone_number', 'phone'),
    email: pick('email'),
    created_time: body.created_time ?? src.created_time,
    campaign_id: body.campaign_id ?? '',
    campaign_name: body.campaign_name ?? '',
    ad_id: body.ad_id ?? src.ad_id,
    ad_name: body.ad_name ?? '',
    adset_id: body.adset_id ?? '',
    form_id: body.form_id ?? src.form_id,
    form_name: body.form_name ?? '',
    custom_fields: fields,
    inbound_message: '',
  },
}];

// E.164 normalisation. DEFAULT_COUNTRY_CODE is the country the ad runs in;
// it is only applied to numbers that are clearly local (leading 0 or bare
// national length). A number that already carries a country code is left
// alone — guessing at those is how you text the wrong person.
const DEFAULT_CC = ($env.DEFAULT_COUNTRY_CODE || '92').replace(/\D/g, '');

function normalise(raw) {
  if (!raw) return { ok: false, reason: 'missing' };
  let s = String(raw).trim();
  const hadPlus = s.startsWith('+');
  s = s.replace(/[^\d]/g, '');
  if (!s) return { ok: false, reason: 'no digits' };

  if (s.startsWith('00')) s = s.slice(2);            // 0092... -> 92...
  else if (hadPlus) { /* already international */ }
  else if (s.startsWith('0')) s = DEFAULT_CC + s.slice(1);  // 0300... -> 92300...
  else if (!s.startsWith(DEFAULT_CC)) s = DEFAULT_CC + s;   // bare national

  if (s.length < 8 || s.length > 15) return { ok: false, reason: `implausible length ${s.length}` };
  return { ok: true, e164: `+${s}`, wa_id: s };
}

return $input.all().map((item) => {
  const r = normalise(item.json.phone_raw);
  if (!r.ok) {
    throw new Error(`Unusable phone for lead ${item.json.lead_id}: ${r.reason}`);
  }
  return { json: { ...item.json, phone: r.e164, wa_id: r.wa_id } };
});

// Existing lead: rehydrate the stored conversation so Claude is never
// stateless. conversation_history lives in the sheet as a JSON string.
const crm = $input.first().json;
const evt = $('Normalize Phone').first().json;

let history = [];
try {
  history = JSON.parse(crm.conversation_history || '[]');
  if (!Array.isArray(history)) history = [];
} catch { history = []; }

return [{
  json: {
    ...evt,
    is_new_lead: false,
    row_number: crm.row_number ?? crm.__rowNum ?? null,
    conversation_id: crm.conversation_id || `conv_${evt.lead_id}`,
    conversation_status: crm.conversation_status || 'open',
    qualification_status: crm.qualification_status || 'unqualified',
    appointment_status: crm.appointment_status || 'none',
    appointment_id: crm.appointment_id || '',
    appointment_date: crm.appointment_date || '',
    appointment_time: crm.appointment_time || '',
    preferred_date: crm.preferred_date || '',
    preferred_time: crm.preferred_time || '',
    last_event_id: crm.last_event_id || '',
    conversation_history: history,
    created_at: crm.created_at || new Date().toISOString(),
    name: crm.name || evt.full_name,
    email: crm.email || evt.email,
  },
}];

// New lead: initialise conversation state. Same shape the existing-lead
// branch produces, so everything downstream sees one contract.
const evt = $('Normalize Phone').first().json;

return [{
  json: {
    ...evt,
    is_new_lead: true,
    row_number: null,
    conversation_id: `conv_${evt.lead_id}`,
    conversation_status: 'open',
    qualification_status: 'unqualified',
    appointment_status: 'none',
    appointment_id: '',
    appointment_date: '',
    appointment_time: '',
    preferred_date: '',
    preferred_time: '',
    last_event_id: evt.event_id,
    conversation_history: [],
    created_at: new Date().toISOString(),
    name: evt.full_name,
  },
}];

// One place that builds the prompt payload, so both branches feed Claude
// identically. History is trimmed — an unbounded transcript eventually
// blows the context window and the cost with it.
const MAX_TURNS = Number($env.MAX_HISTORY_TURNS || 20);
const d = $input.first().json;

const history = (d.conversation_history || []).slice(-MAX_TURNS);
const transcript = history.length
  ? history.map((m) => `${m.role === 'assistant' ? 'Agent' : 'Lead'}: ${m.text}`).join('\n')
  : '(no previous messages — this is the first contact)';

const currentMessage = d.inbound_message
  ? d.inbound_message
  : '(no inbound message yet — open the conversation yourself)';

const context = {
  lead_name: d.name || d.full_name || 'there',
  phone: d.phone,
  email: d.email || '(not provided)',
  campaign: d.campaign_name || d.campaign_id || '(unknown campaign)',
  ad: d.ad_name || d.ad_id || '',
  form: d.form_name || d.form_id || '',
  is_new_lead: d.is_new_lead,
  qualification_status: d.qualification_status,
  appointment_status: d.appointment_status,
  appointment_date: d.appointment_date || '',
  appointment_time: d.appointment_time || '',
  preferred_date: d.preferred_date || '',
  preferred_time: d.preferred_time || '',
  custom_fields: d.custom_fields || {},
};

return [{
  json: {
    ...d,
    conversation_history: history,
    ai_context_json: JSON.stringify(context, null, 2),
    transcript,
    current_message: currentMessage,
  },
}];

