// Defensive parse. A model that returns prose instead of JSON must not
// take the lead down with it — we degrade to a safe reply_only turn.
const ctx = $('Prepare WhatsApp Context').first().json;
const raw = $input.first().json;

const text = raw.text ?? raw.output ?? raw.response ?? '';

function extractJson(s) {
  if (!s) return null;
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : s;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(candidate.slice(start, end + 1)); } catch { return null; }
}

const parsed = extractJson(text);
const ok = parsed && typeof parsed.reply === 'string' && parsed.reply.trim();

const ai = ok ? parsed : {
  reply: (text || '').trim().slice(0, 900) ||
    `Hi ${ctx.lead_name || 'there'}, thanks for your interest! How can I help?`,
  intent: 'other',
  qualification_status: ctx.qualification_status || 'unqualified',
  next_action: 'reply_only',
  selected_slot: { date: '', time: '' },
  customer_data: {},
};

// The model is not allowed to book. Only the workflow decides that, and only
// from a slot that was genuinely offered.
const offered = (ctx.conversation_history || [])
  .filter((m) => m.role === 'assistant' && Array.isArray(m.slots))
  .flatMap((m) => m.slots);

let nextAction = ['reply_only', 'check_availability', 'book_appointment', 'handoff_human']
  .includes(ai.next_action) ? ai.next_action : 'reply_only';

const slot = ai.selected_slot || {};
if (nextAction === 'book_appointment') {
  const valid = slot.date && slot.time &&
    (offered.length === 0 || offered.some((s) => s.date === slot.date && s.time === slot.time));
  if (!valid) nextAction = 'check_availability';
}

return [{
  json: {
    ...ctx,
    ai_reply: String(ai.reply).slice(0, 4000),
    intent: ai.intent || 'other',
    qualification_status: ['unqualified', 'qualified', 'disqualified']
      .includes(ai.qualification_status) ? ai.qualification_status : (ctx.qualification_status || 'unqualified'),
    next_action: nextAction,
    selected_slot: slot,
    ai_customer_data: ai.customer_data || {},
    ai_parse_ok: !!ok,
  },
}];

// The AI errored (rate limit, timeout, bad key). Do not go silent on the
// lead and do not pretend the model spoke — send a neutral holding line.
const ctx = $('Prepare WhatsApp Context').first().json;
return [{
  json: {
    ...ctx,
    ai_reply: `Hi ${ctx.lead_name || 'there'}, thanks for reaching out! One of our team will be with you shortly.`,
    intent: 'other',
    qualification_status: ctx.qualification_status || 'unqualified',
    next_action: 'handoff_human',
    selected_slot: {},
    ai_customer_data: {},
    ai_parse_ok: false,
    ai_error: $json.error?.message ?? 'AI node failed',
  },
}];

// Turn real slots into the message. If the provider gave us nothing —
// or fell over — we say so honestly instead of inventing times.
const ctx = $('Parse AI Reply').first().json;
const res = $input.first().json;
const status = res.statusCode ?? 200;
const body = res.body ?? res;

let slots = [];
if (status < 400) {
  const arr = Array.isArray(body) ? body : (body?.slots ?? body?.data ?? []);
  slots = (Array.isArray(arr) ? arr : [])
    .map((s) => ({ date: s.date ?? s.start?.slice(0, 10), time: s.time ?? s.start?.slice(11, 16), id: s.id ?? '' }))
    .filter((s) => s.date && s.time)
    .slice(0, 5);
}

let message;
if (status >= 400) {
  message = `${ctx.ai_reply}\n\nI'm having trouble reaching the calendar right now — I'll get back to you with times shortly.`;
} else if (!slots.length) {
  message = `${ctx.ai_reply}\n\nWe're fully booked for the next few days. Would a later date work for you?`;
} else {
  const list = slots.map((s, i) => `${i + 1}. ${s.date} at ${s.time}`).join('\n');
  message = `${ctx.ai_reply}\n\nHere's what we have open:\n${list}\n\nReply with the number that suits you.`;
}

return [{
  json: {
    ...ctx,
    outbound_message: message,
    offered_slots: slots,
    appointment_status: slots.length ? 'slots_offered' : ctx.appointment_status,
  },
}];

// The single gate that decides whether the lead is told "booked".
// Anything other than a 2xx with a confirmation id is a failure, full stop.
const ctx = $('Parse AI Reply').first().json;
const res = $input.first().json;
const status = res.statusCode ?? 0;
const body = res.body ?? res;

const id = body?.id ?? body?.appointment_id ?? body?.booking_id ?? '';
const confirmed = status >= 200 && status < 300 && !!id;

const slot = ctx.selected_slot || {};

return [{
  json: {
    ...ctx,
    booking_confirmed: confirmed,
    appointment_id: confirmed ? String(id) : '',
    appointment_status: confirmed ? 'booked' : 'booking_failed',
    appointment_date: confirmed ? slot.date : '',
    appointment_time: confirmed ? slot.time : '',
    booking_error: confirmed ? '' : `status ${status}: ${JSON.stringify(body).slice(0, 300)}`,
    outbound_message: confirmed
      ? `Done! You're booked for ${slot.date} at ${slot.time}. We'll send a reminder before then. See you soon!`
      : `I wasn't able to lock that slot in just now — someone from our team will confirm with you shortly. Sorry about that!`,
  },
}];

// Record what actually happened, including a WhatsApp failure - the CRM
// must never claim we messaged someone we did not.
// $input is the Send WhatsApp Reply response; the branch that fed it carries
// the state, so pull that from the node that built it.
const prev = $input.first().json;
const status = prev.statusCode ?? 200;
const body = prev.body ?? prev;
const delivered = status >= 200 && status < 300;

const state = $('Parse AI Reply').first().json;

// Whichever branch ran last wrote outbound_message / booking fields onto the
// item; keep them, they are more specific than the AI state.
const branch = prev;

const history = [...(state.conversation_history || [])];
if (state.current_message && !state.current_message.startsWith('(no inbound')) {
  history.push({ role: 'user', text: state.current_message, at: new Date().toISOString() });
}
history.push({
  role: 'assistant',
  text: branch.outbound_message ?? state.ai_reply,
  slots: branch.offered_slots ?? [],
  at: new Date().toISOString(),
  delivered,
});

return [{
  json: {
    ...state,
    ...branch,
    whatsapp_delivered: delivered,
    whatsapp_error: delivered ? '' : `status ${status}: ${JSON.stringify(body).slice(0, 300)}`,
    whatsapp_message_id: body?.messages?.[0]?.id ?? '',
    conversation_history_json: JSON.stringify(history.slice(-40)),
    updated_at: new Date().toISOString(),
  },
}];

